function render(){const s=scenes[current]; document.title=`AgentDesk 设计稿 · ${s[1]}`; $('#journey').innerHTML=`<header class="reviewbar"><strong>AgentDesk · 全流程设计稿</strong><span>示例画面，不连接工具、不读取仓库、不执行操作</span><a href="/?legacy=1">原设计稿</a><button data-review-toggle>页面目录 ☰</button></header><div class="review-layout"><aside class="review-index"><h2>评审目录</h2><p>按安装到验收的顺序浏览</p>${scenes.map((x,n)=>`${n===0||x[0]!==scenes[n-1][0]?`<h3>${x[0]}</h3>`:''}<button class="${n===current?'selected':''}" data-scene="${n}"><span>${String(n+1).padStart(2,'0')}</span>${x[1]}</button>`).join('')}</aside><div class="review-stage">${content(current)}<section class="review-notes"><div><small>这个页面解决什么</small><p>${s[2]}</p></div><div><small>用户怎么操作</small><p>${s[3]}</p></div><div><small>实现与评审边界</small><p>${s[4]}</p></div></section><footer class="review-footer">${button('← 上一页',Math.max(0,current-1))}<span>${current+1} / ${scenes.length} · ${s[1]}</span>${button(current===scenes.length-1?'回到第一步':'下一页 →',current===scenes.length-1?0:current+1,true)}</footer></div></div><div id="design-toast" role="status"></div>`;}
document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.scene!==undefined){location.hash=target.dataset.scene; if(current===Number(target.dataset.scene))render();}else if(target.hasAttribute('data-details')){showDetails=!showDetails;render();}else if(target.hasAttribute('data-review-toggle')){$('.review-index').classList.toggle('open');}else if(target.dataset.note){$('#design-toast').textContent=target.dataset.note;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>{$('#design-toast').textContent='';},3500);}});
window.addEventListener('hashchange',()=>{current=Math.max(0,Math.min(scenes.length-1,Number(location.hash.slice(1))||0));render();window.scrollTo(0,0);});
render();
